xpath.script:
// Initialize Eruda immediately
eruda.init();
window.debug_data = {}

// --- Global Debug Helper ---
window.odooDebug = function (data) {
    let label = Object.keys(data)[0];
    data = data[label];
    window.debug_data[label] = data;
    console.log(`✅ Dumped '${label}'`);
    console.dir(data);
};
